// Interface texts (FR, EN, AR), v2. Sentences about results are templates filled with the numbers of case.json;
// their direction (higher / lower / mixed, within / beyond) comes from the data, never from the template.
import type { Params } from "./contract";

export type Lang = "fr" | "en" | "ar";
export const LANGS: Lang[] = ["fr", "en", "ar"];
export const LOCALE: Record<Lang, string> = { fr: "fr-FR", en: "en-GB", ar: "ar-MA" };

export interface Fmt {
  num: (v: number | null | undefined, digits?: number) => string;
  pct: (v: number | null | undefined, digits?: number) => string;
  km2: (v: number | null | undefined) => string;
  date: (iso: string | null | undefined) => string;
  datetime: (iso: string | null | undefined) => string;
  coord: (lon: number, lat: number) => string;
}

type Tpl = (p: Params, f: Fmt, t: (k: string, p?: Params) => string) => string;
type Entry = string | Tpl;
export type Dict = Record<string, Entry>;

const n = (p: Params, k: string) => (typeof p[k] === "number" ? (p[k] as number) : null);
const s = (p: Params, k: string) => (p[k] == null ? "" : String(p[k]));
const rows = (p: Params) => (Array.isArray(p.rows) ? (p.rows as unknown[][]) : []);

